<?php
require __DIR__.'/../app/bootstrap.php';require_admin();$db=database();
if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf('activities',$_POST['csrf']??null)){try{activity_create($db,trim($_POST['admin_name']??''),trim($_POST['public_title']??''),trim($_POST['slug']??''),isset($_POST['duplicate'])?(int)$_POST['duplicate']:null);header('Location: /admin/activities.php',true,303);exit;}catch(Throwable $e){$error=$e->getMessage();}}
$rows=$db->query('SELECT a.*,d.draft_revision,d.published_revision,(SELECT COUNT(*) FROM interest_submissions i WHERE i.activity_id=a.id) responses FROM activities a LEFT JOIN content_documents d ON d.activity_id=a.id ORDER BY a.is_root DESC,a.updated_at DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/template/page.css"><title>Activities</title></head><body><main class="section"><p><a href="/admin/interests.php">Responses</a></p><h1>Activities</h1><?php if(isset($error)):?><p><?=h($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token('activities'))?>"><label>Name <input name="admin_name" required></label><label>Public title <input name="public_title" required></label><label>Slug <input name="slug" required></label><button>Create activity</button></form><?php foreach($rows as $r):?><article><h2><?=h($r['admin_name'])?></h2><p>/<?=h($r['slug'])?> · <?=h($r['status'])?> · draft <?=h($r['draft_revision'])?> · published <?=h($r['published_revision'])?> · <?=h($r['responses'])?> responses</p><p><a href="/editor/?activity=<?=$r['id']?>">Edit</a> · <a href="/admin/preview.php?activity=<?=$r['id']?>">Preview</a> · <a href="/<?=h($r['slug'])?>/">Public page</a></p></article><?php endforeach;?></main></body></html>
